mapper.select:
select

from tables tbl
where tbl.name = #{name,jdbcType=VARCHAR}
      and tbl.floor_id = #{floorId,jdbcType=INTEGER}
      and tbl.store_id = #{storeId,jdbcType=INTEGER}
      and tbl.deleted_at is null

mapper.delete:
update tables
set deleted_at = #{deletedAt,jdbcType=TIMESTAMP}
where id = #{id,jdbcType=INTEGER}
